        public static string Get(string key, string lang)
        {
            string[] row;
            if (!Table.TryGetValue(key, out row)) return "[" + key + "]";
            int i = Array.IndexOf(Languages, lang);
            if (i < 0) i = 0;
            return row[i];
        }
    }
